def latest(family,predicate=lambda d:True):
 candidates=[]
 for p in (scope/'results'/family).glob('*/result.json'):
  d=json.loads(p.read_text())
  if predicate(d):candidates.append((p,d))
 if not candidates:raise ValueError('Missing final evidence '+family)
 return sorted(candidates,key=lambda v:v[0].parent.name)[-1]
